"    let discountAmt = 0;
    if (discount.type === 'PERCENT' || discount.type === 'percent') {
      discountAmt = subtotal * (parseFloat(discount.value || 0) / 100);
    } else if (discount.type === 'FIXED' || discount.type === 'fixed') {
      discountAmt = parseFloat(discount.value || 0);
    }

    const pointsDiscountAmt = (redeemedPoints || 0) * 1;
    const totalDiscountAmt = discountAmt + pointsDiscountAmt;

    const amountAfterDiscount = Math.max(0, subtotal - totalDiscountAmt);
    const taxRate = parseFloat(posSettings.taxRate || 0);
    const isInclusive = posSettings.isTaxInclusive;

    let tax = 0;
    let taxableAmount = amountAfterDiscount;

    if (isInclusive) {
      tax = amountAfterDiscount * (taxRate / (100 + taxRate)); // Extract tax
      taxableAmount = amountAfterDiscount - tax;
    } else {
      tax = amountAfterDiscount * (taxRate / 100); // Calculate tax on top
    }

    const cgst = tax / 2;
    const sgst = tax / 2;

    const serviceCharge = orderType === 'DINE_IN' && posSettings.enableServiceCharge
      ? (taxableAmount * (parseFloat(posSettings.serviceChargeRate || 5) / 100))
      : 0;

    let additionalChargesAmt = 0;
    appliedAdditionalCharges.forEach(chg => {
      const val = parseFloat(chg.value || 0);
      if (chg.type === 'percent' || chg.type === 'PERCENT') {
        additionalChargesAmt += amountAfterDiscount * (val / 100);
      } else {
        additionalChargesAmt += val;
      }
    });

    const extraFixed = parseFloat(extraCharges.packing || 0) + parseFloat(extraCharges.delivery || 0) + additionalChargesAmt;
    const total = isInclusive ? amountAfterDiscount + serviceCharge + extraFixed : taxableAmount + tax + serviceCharge + extraFixed;

    return {
      subtotal,
      tax,
      cgst,
      sgst,
      serviceCharge,
      total,
      extraFixed,
      discountAmt,
      pointsDiscountAmt,
      totalDiscountAmt
    };"

